{
}

Method.Source:
    /// <summary>
    /// Validating the State Prefix
    /// </summary>
    /// <returns>boolean value</returns>
    public boolean validateWrite()
    {
        boolean     ret, state;

        ret = next validateWrite();

        state = (strlen(int2Str(this.METStatePrefix))) == strlen(strkeep(int2Str(this.METStatePrefix), METConstants::statePrefixInt));
        // Validate State prefix
        if (!state)
        {
            ret = checkFailed("@MET:METStatePrefixEntityValidation");
        }

        return ret;
    }
